def encode_amount(dollars: str) -> str:
    if dollars.startswith('-'):
        sign = '-'
        amount_str = dollars[1:]
    elif dollars.startswith('+'):
        sign = '+'
        amount_str = dollars[1:]
    else:
        sign = '+'
        amount_str = dollars

    if '.' in amount_str:
        parts = amount_str.split('.')
        dollars_val = int(parts[0]) if parts[0] else 0
        cents_str = parts[1]

        if len(cents_str) == 1:
            cents_val = int(cents_str) * 10
        elif len(cents_str) == 2:
            cents_val = int(cents_str)
        else:
            cents_val = int(cents_str[:2])
    else:
        dollars_val = int(amount_str)
        cents_val = 0

    total_cents = dollars_val * 100 + cents_val
    digits_str = str(total_cents)
    check = sum(int(d) for d in digits_str) % 10

    return f"{sign}{digits_str}#{check}"

